 46	static void advance_location(GrammarLexer *lexer, char c)
 47	{
 48	    lexer->pos++;
 49	    if (c == '\n') {
 50	        lexer->loc.line++;
 51	        lexer->loc.column = 1;
 52	    } else {
 53	        lexer->loc.column++;
 54	    }
 55	}
