 63	static GrammarToken grammar_next(GrammarLexer *lexer)
 64	{
 65	    GrammarToken token;
 66	    size_t start;
 67	    size_t out;
 68	    token.kind = G_EOF;
 69	    token.text = NULL;
 70	    token.loc = lexer->loc;
 71	    while (lexer->pos < lexer->length) {
 72	        char c = lexer->source[lexer->pos];
 73	        if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
 74	            advance_location(lexer, c);
 75	        } else if (c == '#') {
 76	            while (lexer->pos < lexer->length && lexer->source[lexer->pos] != '\n')
 77	                advance_location(lexer, lexer->source[lexer->pos]);
 78	        } else {
 79	            break;
 80	        }
 81	    }
 82	    token.loc = lexer->loc;
 83	    if (lexer->pos == lexer->length)
 84	        return token;
 85	    start = lexer->pos;
 86	    if ((lexer->source[lexer->pos] >= 'A' && lexer->source[lexer->pos] <= 'Z') ||
 87	        (lexer->source[lexer->pos] >= 'a' && lexer->source[lexer->pos] <= 'z') ||
 88	        lexer->source[lexer->pos] == '_') {
 89	        advance_location(lexer, lexer->source[lexer->pos]);
 90	        while (lexer->pos < lexer->length) {
 91	            char c = lexer->source[lexer->pos];
 92	            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
 93	                  (c >= '0' && c <= '9') || c == '_'))
 94	                break;
 95	            advance_location(lexer, c);
 96	        }
 97	        token.kind = G_IDENT;
 98	        token.text = copy_text(lexer->source + start, lexer->pos - start);
 99	        if (token.text == NULL)
100	            lex_error(lexer, token.loc, "out of memory");
101	        return token;
102	    }
103	    if (lexer->source[lexer->pos] == '%') {
104	        advance_location(lexer, '%');
105	        start = lexer->pos;
106	        while (lexer->pos < lexer->length) {
107	            char c = lexer->source[lexer->pos];
108	            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_'))
109	                break;
110	            advance_location(lexer, c);
111	        }
112	        if (start == lexer->pos) {
113	            lex_error(lexer, token.loc, "expected directive name");
114	            token.kind = G_BAD;
115	            return token;
116	        }
117	        token.kind = G_PERCENT;
118	        token.text = copy_text(lexer->source + start, lexer->pos - start);
119	        if (token.text == NULL)
120	            lex_error(lexer, token.loc, "out of memory");
121	        return token;
122	    }
123	    if (lexer->source[lexer->pos] == '\'') {
124	        advance_location(lexer, '\'');
125	        out = 0;
126	        token.text = (char *)malloc(1);
127	        if (token.text == NULL) {
128	            lex_error(lexer, token.loc, "out of memory");
129	            token.kind = G_BAD;
130	            return token;
131	        }
132	        while (lexer->pos < lexer->length && lexer->source[lexer->pos] != '\'') {
133	            char c = lexer->source[lexer->pos];
134	            if (c == '\\') {
135	                advance_location(lexer, c);
136	                if (lexer->pos == lexer->length ||
137	                    (lexer->source[lexer->pos] != '\'' && lexer->source[lexer->pos] != '\\')) {
138	                    lex_error(lexer, lexer->loc, "unsupported string escape");
139	                    grammar_token_free(&token);
140	                    token.kind = G_BAD;
141	                    return token;
142	                }
143	                c = lexer->source[lexer->pos];
144	            }
145	            {
146	                char *grown = (char *)realloc(token.text, out + 2);
147	                if (grown == NULL) {
148	                    lex_error(lexer, token.loc, "out of memory");
149	                    grammar_token_free(&token);
150	                    token.kind = G_BAD;
151	                    return token;
152	                }
153	                token.text = grown;
154	            }
155	            token.text[out++] = c;
156	            token.text[out] = '\0';
157	            advance_location(lexer, c);
158	        }
159	        if (lexer->pos == lexer->length) {
160	            lex_error(lexer, token.loc, "unterminated grammar string");
161	            grammar_token_free(&token);
162	            token.kind = G_BAD;
163	            return token;
164	        }
165	        advance_location(lexer, '\'');
166	        token.kind = G_STRING;
167	        return token;
168	    }
169	    advance_location(lexer, lexer->source[lexer->pos]);
170	    switch (lexer->source[start]) {
171	    case ':':
172	        if (lexer->pos + 1 < lexer->length && lexer->source[lexer->pos] == ':' &&
173	            lexer->source[lexer->pos + 1] == '=') {
174	            advance_location(lexer, ':');
175	            advance_location(lexer, '=');
176	            token.kind = G_ASSIGN;
177	        } else {
178	            token.kind = G_BAD;
179	            lex_error(lexer, token.loc, "expected ::= operator");
180	        }
181	        break;
182	    case '|': token.kind = G_PIPE; break;
183	    case ';': token.kind = G_SEMI; break;
184	    case '$': token.kind = G_DOLLAR; break;
185	    default:
186	        token.kind = G_BAD;
187	        lex_error(lexer, token.loc, "invalid grammar character");
188	        break;
189	    }
190	    return token;
191	}
