206	static int grow_array(void **data, size_t *capacity, size_t item_size, size_t needed)
207	{
208	    size_t next = *capacity == 0 ? 4 : *capacity;
209	    void *grown;
210	    while (next < needed) {
211	        if (next > ((size_t)-1) / 2)
212	            return -1;
213	        next *= 2;
214	    }
215	    grown = realloc(*data, next * item_size);
216	    if (grown == NULL)
217	        return -1;
218	    *data = grown;
219	    *capacity = next;
220	    return 0;
221	}
