402	static int validate_grammar(Grammar *grammar, Diagnostic *diagnostic)
403	{
404	    size_t i;
405	    size_t *nullable;
406	    unsigned char *edges;
407	    size_t *indegree;
408	    size_t *queue;
409	    int changed;
410	    if (find_rule(grammar, grammar->start_name) == (size_t)-1) {
411	        diagnostic_set(diagnostic, (Location){0, 1, 1}, "start rule is not defined");
412	        return -1;
413	    }
414	    grammar->start_rule = find_rule(grammar, grammar->start_name);
415	    for (i = 0; i < grammar->rule_count; i++) {
416	        size_t j;
417	        for (j = 0; j < grammar->rules[i].count; j++) {
418	            size_t k;
419	            Alternative *alt = &grammar->rules[i].alternatives[j];
420	            for (k = 0; k < alt->count; k++) {
421	                GrammarSymbol *symbol = &alt->symbols[k];
422	                if (symbol->kind == SYM_NONTERM && find_rule(grammar, symbol->text) == (size_t)-1) {
423	                    diagnostic_setf(diagnostic, (Location){0, 1, 1}, "undefined nonterminal: %s", symbol->text);
424	                    return -1;
425	                }
426	            }
427	        }
428	    }
429	    nullable = (size_t *)calloc(grammar->rule_count, sizeof(*nullable));
430	    edges = (unsigned char *)calloc(grammar->rule_count * grammar->rule_count, sizeof(*edges));
431	    indegree = (size_t *)calloc(grammar->rule_count, sizeof(*indegree));
432	    queue = (size_t *)calloc(grammar->rule_count, sizeof(*queue));
433	    if (nullable == NULL || edges == NULL || indegree == NULL || queue == NULL) {
434	        free(nullable); free(edges); free(indegree); free(queue);
435	        diagnostic_set(diagnostic, (Location){0, 1, 1}, "out of memory");
436	        return -1;
437	    }
438	    do {
439	        changed = 0;
440	        for (i = 0; i < grammar->rule_count; i++) {
441	            size_t j;
442	            for (j = 0; j < grammar->rules[i].count; j++) {
443	                size_t k;
444	                int can_empty = 1;
445	                Alternative *alt = &grammar->rules[i].alternatives[j];
446	                for (k = 0; k < alt->count; k++) {
447	                    if (alt->symbols[k].kind != SYM_NONTERM ||
448	                        !nullable[find_rule(grammar, alt->symbols[k].text)]) {
449	                        can_empty = 0;
450	                        break;
451	                    }
452	                }
453	                if (can_empty && !nullable[i]) {
454	                    nullable[i] = 1;
455	                    changed = 1;
456	                }
457	            }
458	        }
459	    } while (changed);
460	    for (i = 0; i < grammar->rule_count; i++) {
461	        size_t j;
462	        for (j = 0; j < grammar->rules[i].count; j++) {
463	            size_t k;
464	            Alternative *alt = &grammar->rules[i].alternatives[j];
465	            for (k = 0; k < alt->count; k++) {
466	                GrammarSymbol *symbol = &alt->symbols[k];
467	                if (symbol->kind != SYM_NONTERM)
468	                    break;
469	                edges[i * grammar->rule_count + find_rule(grammar, symbol->text)] = 1;
470	                if (!nullable[find_rule(grammar, symbol->text)])
471	                    break;
472	            }
473	        }
474	    }
475	    /* A topological traversal detects every cycle without a fixed rule-depth limit. */
476	    {
477	        size_t head = 0;
478	        size_t tail = 0;
479	        size_t removed = 0;
480	        size_t node;
481	        for (i = 0; i < grammar->rule_count; i++) {
482	            size_t target;
483	            for (target = 0; target < grammar->rule_count; target++)
484	                if (edges[i * grammar->rule_count + target])
485	                    indegree[target]++;
486	        }
487	        for (i = 0; i < grammar->rule_count; i++)
488	            if (indegree[i] == 0)
489	                queue[tail++] = i;
490	        while (head < tail) {
491	            node = queue[head++];
492	            removed++;
493	            for (i = 0; i < grammar->rule_count; i++) {
494	                if (edges[node * grammar->rule_count + i] && --indegree[i] == 0)
495	                    queue[tail++] = i;
496	            }
497	        }
498	        if (removed != grammar->rule_count) {
499	            for (i = 0; i < grammar->rule_count; i++)
500	                if (indegree[i] != 0)
501	                    break;
502	            diagnostic_setf(diagnostic, (Location){0, 1, 1}, "left recursion involving: %s",
503	                            grammar->rules[i].name);
504	            free(nullable); free(edges); free(indegree); free(queue);
505	            return -1;
506	        }
507	    }
508	    free(nullable); free(edges); free(indegree); free(queue);
509	    return 0;
510	}
