512	int grammar_parse(const char *source, size_t length, Grammar *grammar, Diagnostic *diagnostic)
513	{
514	    GrammarParser parser;
515	    memset(grammar, 0, sizeof(*grammar));
516	    memset(diagnostic, 0, sizeof(*diagnostic));
517	    parser.lexer.source = source;
518	    parser.lexer.length = length;
519	    parser.lexer.pos = 0;
520	    parser.lexer.loc = (Location){0, 1, 1};
521	    parser.lexer.diagnostic = diagnostic;
522	    parser.current.kind = G_EOF;
523	    parser.current.text = NULL;
524	    parser.grammar = grammar;
525	    parser.diagnostic = diagnostic;
526	    parser_advance(&parser);
527	    if (!diagnostic->present && parse_directives(&parser) == 0 && parse_rules(&parser) == 0)
528	        (void)validate_grammar(grammar, diagnostic);
529	    grammar_token_free(&parser.current);
530	    if (diagnostic->present) {
531	        grammar_free(grammar);
532	        return -1;
533	    }
534	    return 0;
535	}
