537	int grammar_set_start(Grammar *grammar, const char *name, Diagnostic *diagnostic)
538	{
539	    size_t index = find_rule(grammar, name);
540	    if (index == (size_t)-1) {
541	        diagnostic_setf(diagnostic, (Location){0, 1, 1}, "start override is not defined: %s", name);
542	        return -1;
543	    }
544	    free(grammar->start_name);
545	    grammar->start_name = copy_text(name, strlen(name));
546	    if (grammar->start_name == NULL) {
547	        diagnostic_set(diagnostic, (Location){0, 1, 1}, "out of memory");
548	        return -1;
549	    }
550	    grammar->start_rule = index;
551	    return 0;
552	}
