  6	static char *copy_text(const char *text, size_t length)
  7	{
  8	    char *result = (char *)malloc(length + 1);
  9	    if (result != NULL) {
 10	        memcpy(result, text, length);
 11	        result[length] = '\0';
 12	    }
 13	    return result;
 14	}
