 16	static int grow_tokens(Markup *markup)
 17	{
 18	    size_t capacity = markup->capacity == 0 ? 16 : markup->capacity * 2;
 19	    MarkupToken *grown;
 20	    if (markup->capacity >= markup->count + 1)
 21	        return 0;
 22	    if (capacity < markup->count + 1)
 23	        return -1;
 24	    grown = (MarkupToken *)realloc(markup->tokens, capacity * sizeof(*grown));
 25	    if (grown == NULL)
 26	        return -1;
 27	    markup->tokens = grown;
 28	    markup->capacity = capacity;
 29	    return 0;
 30	}
 31	
 32	static int add_token(Markup *markup, MarkupKind kind, const char *text, size_t length, Location loc)
 33	{
 34	    MarkupToken *token;
 35	    if (grow_tokens(markup) != 0)
 36	        return -1;
 37	    token = &markup->tokens[markup->count++];
 38	    token->kind = kind;
 39	    token->lexeme = copy_text(text, length);
 40	    token->loc = loc;
 41	    if (token->lexeme == NULL) {
 42	        markup->count--;
 43	        return -1;
 44	    }
 45	    return 0;
 46	}
