 48	static void move_location(Location *loc, char c, size_t *offset)
 49	{
 50	    (*offset)++;
 51	    if (c == '\n') {
 52	        loc->line++;
 53	        loc->column = 1;
 54	    } else {
 55	        loc->column++;
 56	    }
 57	}
