 46	static int item_equal(const ChartItem *a, const ChartItem *b)
 47	{
 48	    return a->rule == b->rule && a->alternative == b->alternative &&
 49	           a->dot == b->dot && a->origin == b->origin;
 50	}
 51	
 52	static int vector_grow(ChartItem **data, size_t *capacity, size_t needed)
 53	{
 54	    size_t next = *capacity == 0 ? 16 : *capacity * 2;
 55	    ChartItem *grown;
 56	    if (*capacity >= needed)
 57	        return 0;
 58	    while (next < needed) {
 59	        if (next > ((size_t)-1) / 2)
 60	            return -1;
 61	        next *= 2;
 62	    }
 63	    grown = (ChartItem *)realloc(*data, next * sizeof(*grown));
 64	    if (grown == NULL)
 65	        return -1;
 66	    *data = grown;
 67	    *capacity = next;
 68	    return 0;
 69	}
 70	
 71	static int add_item(ItemVector *vector, ChartItem item)
 72	{
 73	    size_t i;
 74	    for (i = 0; i < vector->count; i++)
 75	        if (item_equal(&vector->data[i], &item))
 76	            return 0;
 77	    if (vector_grow(&vector->data, &vector->capacity, vector->count + 1) != 0)
 78	        return -1;
 79	    vector->data[vector->count++] = item;
 80	    return 1;
 81	}
 82	
 83	static int add_candidate(CandidateVector *vector, ChartItem item, atomic_int *failed)
 84	{
 85	    if (vector_grow(&vector->data, &vector->capacity, vector->count + 1) != 0) {
 86	        atomic_store(failed, 1);
 87	        return -1;
 88	    }
 89	    vector->data[vector->count++] = item;
 90	    return 0;
 91	}
