 93	static size_t rule_index(const Grammar *grammar, const char *name)
 94	{
 95	    size_t i;
 96	    for (i = 0; i < grammar->rule_count; i++)
 97	        if (strcmp(grammar->rules[i].name, name) == 0)
 98	            return i;
 99	    return (size_t)-1;
100	}
101	
102	static const GrammarSymbol *next_symbol(const Grammar *grammar, const ChartItem *item)
103	{
104	    const Alternative *alternative = &grammar->rules[item->rule].alternatives[item->alternative];
105	    if (item->dot >= alternative->count)
106	        return NULL;
107	    return &alternative->symbols[item->dot];
108	}
109	
110	static void closure_task(void *context, size_t worker, size_t begin, size_t end)
111	{
112	    ClosureWork *work = (ClosureWork *)context;
113	    ItemVector *current = &work->charts[work->position];
114	    CandidateVector *out = &work->candidates[worker];
115	    size_t i;
116	    if (begin < end)
117	        work->task_counts[worker]++;
118	    for (i = begin; i < end && !atomic_load(&work->failed); i++) {
119	        ChartItem item = current->data[i];
120	        const GrammarSymbol *symbol = next_symbol(work->grammar, &item);
121	        if (symbol != NULL && symbol->kind == SYM_NONTERM) {
122	            size_t target = rule_index(work->grammar, symbol->text);
123	            size_t j;
124	            for (j = 0; j < work->grammar->rules[target].count; j++) {
125	                ChartItem candidate = {target, j, 0, work->position};
126	                if (add_candidate(out, candidate, &work->failed) != 0)
127	                    return;
128	            }
129	            /* Prediction can follow an epsilon constituent already in this chart. */
130	            for (j = 0; j < current->count; j++) {
131	                ChartItem completed = current->data[j];
132	                if (completed.rule == target && completed.origin == work->position &&
133	                    next_symbol(work->grammar, &completed) == NULL) {
134	                    ChartItem candidate = {item.rule, item.alternative, item.dot + 1, item.origin};
135	                    if (add_candidate(out, candidate, &work->failed) != 0)
136	                        return;
137	                }
138	            }
139	        } else if (symbol == NULL) {
140	            size_t j;
141	            if (item.origin > work->position)
142	                continue;
143	            for (j = 0; j < work->charts[item.origin].count; j++) {
144	                ChartItem parent = work->charts[item.origin].data[j];
145	                const GrammarSymbol *wanted = next_symbol(work->grammar, &parent);
146	                if (wanted != NULL && wanted->kind == SYM_NONTERM &&
147	                    rule_index(work->grammar, wanted->text) == item.rule) {
148	                    ChartItem candidate = {parent.rule, parent.alternative, parent.dot + 1, parent.origin};
149	                    if (add_candidate(out, candidate, &work->failed) != 0)
150	                        return;
151	                }
152	            }
153	        }
154	    }
155	}
156	
157	static int token_matches(const GrammarSymbol *symbol, const MarkupToken *token)
158	{
159	    if (symbol->kind == SYM_LITERAL)
160	        return strcmp(symbol->text, token->lexeme) == 0;
161	    if (symbol->kind == SYM_TOKEN) {
162	        if (symbol->token_kind == TOK_IDENT) return token->kind == MARKUP_IDENT;
163	        if (symbol->token_kind == TOK_STRING) return token->kind == MARKUP_STRING;
164	        return token->kind == MARKUP_TEXT;
165	    }
166	    return 0;
167	}
168	
169	static void scan_task(void *context, size_t worker, size_t begin, size_t end)
170	{
171	    ScanWork *work = (ScanWork *)context;
172	    CandidateVector *out = &work->candidates[worker];
173	    size_t i;
174	    if (end > work->current->count)
175	        end = work->current->count;
176	    if (begin < end)
177	        work->task_counts[worker]++;
178	    for (i = begin; i < end && !atomic_load(&work->failed); i++) {
179	        const ChartItem *item = &work->current->data[i];
180	        const GrammarSymbol *symbol = next_symbol(work->grammar, item);
181	        if (symbol != NULL && symbol->kind != SYM_NONTERM &&
182	            token_matches(symbol, &work->markup->tokens[work->position])) {
183	            ChartItem candidate = {item->rule, item->alternative, item->dot + 1, item->origin};
184	            if (add_candidate(out, candidate, &work->failed) != 0)
185	                return;
186	        }
187	    }
188	}
189	
190	static int candidate_compare(const void *left, const void *right)
191	{
192	    const ChartItem *a = (const ChartItem *)left;
193	    const ChartItem *b = (const ChartItem *)right;
194	    if (a->rule != b->rule) return a->rule < b->rule ? -1 : 1;
195	    if (a->alternative != b->alternative) return a->alternative < b->alternative ? -1 : 1;
196	    if (a->dot != b->dot) return a->dot < b->dot ? -1 : 1;
197	    if (a->origin != b->origin) return a->origin < b->origin ? -1 : 1;
198	    return 0;
199	}
200	
201	static int merge_candidates(ItemVector *target, CandidateVector *vectors)
202	{
203	    size_t total = 0;
204	    size_t i;
205	    ChartItem *all;
206	    size_t at = 0;
207	    for (i = 0; i < 8; i++)
208	        total += vectors[i].count;
209	    if (total == 0)
210	        return 0;
211	    all = (ChartItem *)malloc(total * sizeof(*all));
212	    if (all == NULL)
213	        return -1;
214	    for (i = 0; i < 8; i++) {
215	        memcpy(all + at, vectors[i].data, vectors[i].count * sizeof(*all));
216	        at += vectors[i].count;
217	    }
218	    qsort(all, total, sizeof(*all), candidate_compare);
219	    for (i = 0; i < total; i++) {
220	        if (add_item(target, all[i]) < 0) {
221	            free(all);
222	            return -1;
223	        }
224	    }
225	    free(all);
226	    return 0;
227	}
