229	static void clear_candidates(CandidateVector *vectors)
230	{
231	    size_t i;
232	    for (i = 0; i < 8; i++)
233	        vectors[i].count = 0;
234	}
235	
236	static void free_candidates(CandidateVector *vectors)
237	{
238	    size_t i;
239	    for (i = 0; i < 8; i++)
240	        free(vectors[i].data);
241	}
242	
243	static void free_charts(ItemVector *charts, size_t count)
244	{
245	    size_t i;
246	    for (i = 0; i < count; i++)
247	        free(charts[i].data);
248	    free(charts);
249	}
