251	static void expected_add(char *expected, size_t capacity, const GrammarSymbol *symbol)
252	{
253	    char part[80];
254	    size_t used = strlen(expected);
255	    if (symbol->kind == SYM_LITERAL)
256	        (void)snprintf(part, sizeof(part), "'%s'", symbol->text);
257	    else if (symbol->token_kind == TOK_IDENT)
258	        (void)snprintf(part, sizeof(part), "$IDENT");
259	    else if (symbol->token_kind == TOK_STRING)
260	        (void)snprintf(part, sizeof(part), "$STRING");
261	    else
262	        (void)snprintf(part, sizeof(part), "$TEXT");
263	    if (used != 0 && used + 2 < capacity) {
264	        (void)strncat(expected, ", ", capacity - used - 1);
265	        used += 2;
266	    }
267	    if (used + strlen(part) + 1 < capacity)
268	        (void)strncat(expected, part, capacity - used - 1);
269	}
