271	int recognize(const Grammar *grammar, const Markup *markup, Recognition *result)
272	{
273	    WorkerPool pool;
274	    ItemVector *charts;
275	    CandidateVector candidates[8];
276	    size_t chart_count = markup->count + 1;
277	    size_t position;
278	    int pool_ok = 0;
279	    memset(result, 0, sizeof(*result));
280	    memset(&pool, 0, sizeof(pool));
281	    memset(candidates, 0, sizeof(candidates));
282	    charts = (ItemVector *)calloc(chart_count, sizeof(*charts));
283	    if (charts == NULL)
284	        return -1;
285	    if (pool_start(&pool) != 0) {
286	        free_charts(charts, chart_count);
287	        return -1;
288	    }
289	    pool_ok = 1;
290	    for (position = 0; position < grammar->rules[grammar->start_rule].count; position++) {
291	        ChartItem seed = {grammar->start_rule, position, 0, 0};
292	        if (add_item(&charts[0], seed) < 0)
293	            goto failed;
294	    }
295	    for (position = 0; position <= markup->count; position++) {
296	        size_t processed = 0;
297	        while (processed < charts[position].count) {
298	            ClosureWork work;
299	            size_t snapshot = charts[position].count;
300	            clear_candidates(candidates);
301	            work.grammar = grammar;
302	            work.charts = charts;
303	            work.position = position;
304	            work.candidates = candidates;
305	            work.task_counts = result->tasks;
306	            atomic_init(&work.failed, 0);
307	            if (pool_run_range(&pool, processed, snapshot, closure_task, &work) != 0 ||
308	                atomic_load(&work.failed))
309	                goto failed;
310	            result->rounds++;
311	            if (merge_candidates(&charts[position], candidates) != 0)
312	                goto failed;
313	            processed = snapshot;
314	        }
315	        if (position < markup->count) {
316	            ScanWork work;
317	            clear_candidates(candidates);
318	            work.grammar = grammar;
319	            work.markup = markup;
320	            work.current = &charts[position];
321	            work.position = position;
322	            work.candidates = candidates;
323	            work.task_counts = result->tasks;
324	            atomic_init(&work.failed, 0);
325	            if (pool_run_range(&pool, 0, charts[position].count, scan_task, &work) != 0 ||
326	                atomic_load(&work.failed))
327	                goto failed;
328	            result->rounds++;
329	            if (merge_candidates(&charts[position + 1], candidates) != 0)
330	                goto failed;
331	        }
332	    }
333	    result->accepted = 0;
334	    {
335	        size_t i;
336	        for (i = 0; i < charts[markup->count].count; i++) {
337	            ChartItem item = charts[markup->count].data[i];
338	            if (item.rule == grammar->start_rule && item.origin == 0 &&
339	                next_symbol(grammar, &item) == NULL) {
340	                result->accepted = 1;
341	                break;
342	            }
343	        }
344	    }
345	    if (!result->accepted) {
346	        size_t furthest = 0;
347	        for (position = 0; position <= markup->count; position++) {
348	            size_t i;
349	            int active = 0;
350	            for (i = 0; i < charts[position].count; i++)
351	                if (next_symbol(grammar, &charts[position].data[i]) != NULL)
352	                    active = 1;
353	            if (active)
354	                furthest = position;
355	        }
356	        result->error_position = furthest;
357	        result->expected[0] = '\0';
358	        for (position = 0; position < charts[furthest].count; position++) {
359	            const GrammarSymbol *symbol = next_symbol(grammar, &charts[furthest].data[position]);
360	            if (symbol != NULL && symbol->kind != SYM_NONTERM)
361	                expected_add(result->expected, sizeof(result->expected), symbol);
362	        }
363	        if (result->expected[0] == '\0')
364	            (void)snprintf(result->expected, sizeof(result->expected), "markup token");
365	    }
366	    free_candidates(candidates);
367	    if (pool_ok)
368	        pool_stop(&pool);
369	    free_charts(charts, chart_count);
370	    return 0;
371	
372	failed:
373	    free_candidates(candidates);
374	    if (pool_ok)
375	        pool_stop(&pool);
376	    free_charts(charts, chart_count);
377	    return -1;
378	}
