 10	static int read_file(const char *path, char **data, size_t *length)
 11	{
 12	    FILE *file = fopen(path, "rb");
 13	    long size;
 14	    size_t got;
 15	    char *buffer;
 16	    if (file == NULL)
 17	        return -1;
 18	    if (fseek(file, 0, SEEK_END) != 0) {
 19	        fclose(file);
 20	        return -1;
 21	    }
 22	    size = ftell(file);
 23	    if (size < 0 || fseek(file, 0, SEEK_SET) != 0) {
 24	        fclose(file);
 25	        return -1;
 26	    }
 27	    buffer = (char *)malloc((size_t)size + 1);
 28	    if (buffer == NULL) {
 29	        fclose(file);
 30	        return -1;
 31	    }
 32	    got = fread(buffer, 1, (size_t)size, file);
 33	    fclose(file);
 34	    if (got != (size_t)size) {
 35	        free(buffer);
 36	        return -1;
 37	    }
 38	    buffer[got] = '\0';
 39	    *data = buffer;
 40	    *length = got;
 41	    return 0;
 42	}
