 89	int pool_run(WorkerPool *pool, size_t count, PoolTask task, void *context)
 90	{
 91	    return pool_run_range(pool, 0, count, task, context);
 92	}
 93	
 94	int pool_run_range(WorkerPool *pool, size_t begin, size_t end, PoolTask task, void *context)
 95	{
 96	    size_t i;
 97	    size_t span = end - begin;
 98	    pthread_mutex_lock(&pool->mutex);
 99	    pool->task_count = span;
100	    pool->task = task;
101	    pool->context = context;
102	    pool->completed = 0;
103	    for (i = 0; i < 8; i++) {
104	        pool->begins[i] = begin + (span * i) / 8;
105	        pool->ends[i] = begin + (span * (i + 1)) / 8;
106	    }
107	    pool->generation++;
108	    pthread_cond_broadcast(&pool->work_ready);
109	    while (pool->completed != 8)
110	        pthread_cond_wait(&pool->done, &pool->mutex);
111	    pthread_mutex_unlock(&pool->mutex);
112	    return 0;
113	}
114	
115	void pool_stop(WorkerPool *pool)
116	{
117	    size_t i;
118	    if (!pool->initialized)
119	        return;
120	    pthread_mutex_lock(&pool->mutex);
121	    pool->stopping = 1;
122	    pthread_cond_broadcast(&pool->work_ready);
123	    pthread_mutex_unlock(&pool->mutex);
124	    for (i = 0; i < 8; i++)
125	        pthread_join(pool->threads[i], NULL);
126	    pthread_cond_destroy(&pool->done);
127	    pthread_cond_destroy(&pool->work_ready);
128	    pthread_mutex_destroy(&pool->mutex);
129	    free(pool->begins);
130	    free(pool->ends);
131	    pool->begins = NULL;
132	    pool->ends = NULL;
133	    pool->initialized = 0;
134	}

