 16	static int grow_tokens(Markup *markup)
 17	{
 18	    size_t capacity = markup->capacity == 0 ? 16 : markup->capacity * 2;
 19	    MarkupToken *grown;
 20	    if (markup->capacity >= markup->count + 1)
 21	        return 0;
 22	    if (capacity < markup->count + 1)
 23	        return -1;
 24	    grown = (MarkupToken *)realloc(markup->tokens, capacity * sizeof(*grown));
 25	    if (grown == NULL)
 26	        return -1;
 27	    markup->tokens = grown;
 28	    markup->capacity = capacity;
 29	    return 0;
 30	}
