 38	    token->kind = kind;
 39	    token->lexeme = copy_text(text, length);
 40	    token->loc = loc;
 41	    if (token->lexeme == NULL) {
 42	        markup->count--;
 43	        return -1;
 44	    }
 45	    return 0;
 46	}
