 52	static int vector_grow(ChartItem **data, size_t *capacity, size_t needed)
 53	{
 54	    size_t next = *capacity == 0 ? 16 : *capacity * 2;
 55	    ChartItem *grown;
 56	    if (*capacity >= needed)
 57	        return 0;
 58	    while (next < needed) {
 59	        if (next > ((size_t)-1) / 2)
 60	            return -1;
 61	        next *= 2;
 62	    }
 63	    grown = (ChartItem *)realloc(*data, next * sizeof(*grown));
 64	    if (grown == NULL)
 65	        return -1;
 66	    *data = grown;
 67	    *capacity = next;
 68	    return 0;
 69	}
