 71	static int add_item(ItemVector *vector, ChartItem item)
 72	{
 73	    size_t i;
 74	    for (i = 0; i < vector->count; i++)
 75	        if (item_equal(&vector->data[i], &item))
 76	            return 0;
 77	    if (vector_grow(&vector->data, &vector->capacity, vector->count + 1) != 0)
 78	        return -1;
 79	    vector->data[vector->count++] = item;
 80	    return 1;
 81	}
 82	
 83	static int add_candidate(CandidateVector *vector, ChartItem item, atomic_int *failed)
 84	{
 85	    if (vector_grow(&vector->data, &vector->capacity, vector->count + 1) != 0) {
 86	        atomic_store(failed, 1);
 87	        return -1;
 88	    }
 89	    vector->data[vector->count++] = item;
 90	    return 0;
 91	}
