102	static const GrammarSymbol *next_symbol(const Grammar *grammar, const ChartItem *item)
103	{
104	    const Alternative *alternative = &grammar->rules[item->rule].alternatives[item->alternative];
105	    if (item->dot >= alternative->count)
106	        return NULL;
107	    return &alternative->symbols[item->dot];
108	}
